package io.tornado.scheduler;
import io.tornado.datafetch.BinanceMarketDataClient;import io.tornado.persistence.*;import io.tornado.reporting.*;import io.tornado.strategies.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.*;import org.ta4j.core.BarSeries;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class PredictionService{
 private static final Logger log=LoggerFactory.getLogger(PredictionService.class);public static final List<Duration>AUTOMATIC_HORIZONS=List.of(Duration.ofMinutes(1),Duration.ofMinutes(15),Duration.ofMinutes(30),Duration.ofHours(1),Duration.ofHours(4),Duration.ofHours(12),Duration.ofHours(24));private static final BigDecimal MINIMUM_CORRECT_MOVE=new BigDecimal("0.003");private static final int MAX_GRADING_ATTEMPTS=5;private final CoinRepository coins;private final PredictionRepository predictions;private final AnalysisRunRepository runs;private final BinanceMarketDataClient market;private final BestMixService bestMixes;private final MixTradeSimulationService simulations;private final StrategyProfileResolver profileResolver;
 @Autowired public PredictionService(CoinRepository c,PredictionRepository p,AnalysisRunRepository r,BinanceMarketDataClient m,BestMixService b,MixTradeSimulationService s,StrategyProfileResolver resolver){coins=c;predictions=p;runs=r;market=m;bestMixes=b;simulations=s;profileResolver=resolver;}public PredictionService(CoinRepository c,PredictionRepository p,AnalysisRunRepository r,BinanceMarketDataClient m){this(c,p,r,m,null,null,null);}
 public RunResult snapshot(){return snapshot("Scheduled analysis "+Instant.now());}
 public RunResult snapshot(String name){AnalysisRun run=runs.save(new AnalysisRun(name,Duration.ZERO));int saved=0;List<String>errors=new ArrayList<>();List<Coin>activeCoins=coins.findAllByActiveTrueOrderBySymbol();Map<Long,List<StrategyHorizonProfile>>resolved=profileResolver==null?fallback(activeCoins):profileResolver.resolve(activeCoins);Map<CandleKey,BarSeries>seriesCache=new HashMap<>();for(Coin coin:activeCoins){List<Draft>drafts=new ArrayList<>();for(StrategyHorizonProfile profile:resolved.getOrDefault(coin.getId(),List.of()))try{BarSeries series=seriesCache.computeIfAbsent(new CandleKey(coin.getPair(),profile.getAnalysisTimeframe()),key->market.candles(key.pair(),key.timeframe()));StrategyDefinition strategy=StrategyDefinition.valueOf(profile.getStrategyCode());var signal=strategy.evaluate(series,profile.getParameterKey());if(signal.direction()!=Direction.NEUTRAL){var last=series.getLastBar();drafts.add(new Draft(profile,strategy.label(),last.getEndTime(),new BigDecimal(last.getClosePrice().toString()),signal.direction()));}}catch(Exception e){log.warn("Horizon-aware signal failed for {} {} {}: {}",coin.getPair(),profile.getStrategyCode(),profile.getPredictionHorizonSeconds(),e.getMessage());errors.add(coin.getPair()+"/"+profile.getStrategyCode()+"/"+profile.getPredictionHorizonSeconds()+": "+e.getMessage());}if(drafts.isEmpty())continue;try{BigDecimal executionPrice=market.price(coin.getPair());Instant executionAt=Instant.now();List<Prediction>batch=drafts.stream().filter(d->!d.signalAt().isAfter(executionAt)).map(d->new Prediction(run,coin,d.profile(),d.method(),d.signalAt(),d.signalPrice(),executionAt,executionPrice,d.direction())).toList();predictions.saveAll(batch);saved+=batch.size();if(simulations!=null)try{simulations.detect(coin,batch,executionAt,executionPrice);}catch(Exception e){log.error("Mix signal detection failed for {} without affecting snapshot",coin.getPair(),e);}}catch(Exception e){log.error("Execution price failed for {}",coin.getPair(),e);errors.add(coin.getPair()+": "+e.getMessage());}}run.complete(errors.size(),saved);runs.save(run);return new RunResult(run.getId(),saved,errors);}
 private Map<Long,List<StrategyHorizonProfile>>fallback(List<Coin>active){Map<Long,List<StrategyHorizonProfile>>r=new HashMap<>();Instant now=Instant.now();for(Coin coin:active){List<StrategyHorizonProfile>list=new ArrayList<>();for(var strategy:StrategyDefinition.values())for(long horizon:StrategyProfilePolicy.HORIZONS)list.add(StrategyHorizonProfile.fallback(strategy.code(),strategy.version(),horizon,StrategyProfilePolicy.fallback(horizon),strategy.defaultParameterKey(),now));r.put(coin.getId(),list);}return r;}
 @Transactional public int gradeDue(){int count=0;Instant now=Instant.now();Set<BestMixService.Slice>affected=new HashSet<>();Map<TargetKey,PriceLookup>prices=new HashMap<>();Map<TargetKey,List<Prediction>>due=new LinkedHashMap<>();List<Prediction>pending=new ArrayList<>(predictions.findDue(Outcome.PENDING,2,now));pending.addAll(predictions.findDue(Outcome.PENDING,3,now));for(Prediction p:pending){Instant target=p.getTargetAt()!=null?p.getTargetAt():p.getPredictedAt().plusSeconds(p.getHorizonSeconds());due.computeIfAbsent(new TargetKey(p.getCoin().getPair(),target),x->new ArrayList<>()).add(p);}for(var entry:due.entrySet()){TargetKey key=entry.getKey();PriceLookup lookup=prices.computeIfAbsent(key,this::lookup);if(lookup.price()!=null){for(Prediction p:entry.getValue()){p.grade(lookup.price().price(),lookup.price().observedAt(),now,MINIMUM_CORRECT_MOVE);if(bestMixes!=null&&p.getSignalVersion()==3)affected.add(new BestMixService.Slice(p.getCoin().getId(),p.getHorizonSeconds()));count++;}continue;}int terminal=0;for(Prediction p:entry.getValue()){p.recordGradingError(lookup.error());if(p.getGradingAttempts()>=MAX_GRADING_ATTEMPTS){p.markUngradable(now);terminal++;}}int attempt=entry.getValue().stream().mapToInt(Prediction::getGradingAttempts).max().orElse(0);if(terminal>0)log.error("Could not grade {} predictions for {} at {}; {} became UNGRADABLE after {} attempts: {}",entry.getValue().size(),key.pair(),key.target(),terminal,MAX_GRADING_ATTEMPTS,lookup.error());else log.warn("Could not grade {} predictions for {} at {} (attempt {}/{}): {}",entry.getValue().size(),key.pair(),key.target(),attempt,MAX_GRADING_ATTEMPTS,lookup.error());}if(bestMixes!=null&&!affected.isEmpty()){Set<BestMixService.Slice>slices=Set.copyOf(affected);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){try{bestMixes.refresh(slices);}catch(Exception e){log.error("Best-mix refresh failed after grading committed",e);}}});}return count;}
 private PriceLookup lookup(TargetKey key){try{return new PriceLookup(market.priceAt(key.pair(),key.target()),null);}catch(Exception e){return new PriceLookup(null,e.getMessage());}}private record TargetKey(String pair,Instant target){}private record PriceLookup(BinanceMarketDataClient.TimedPrice price,String error){}private record CandleKey(String pair,String timeframe){}private record Draft(StrategyHorizonProfile profile,String method,Instant signalAt,BigDecimal signalPrice,Direction direction){}public record RunResult(long runId,int predictionsCreated,List<String>errors){}
}
